def parse_duration(s):
    import re

    def get_multiplier(unit):
        if unit == 's':
            # Check if number ends in 5
            return 60 if s.rsplit(unit, 1)[0].endswith('5') else 1
        elif unit == 'm':
            # Check if number is odd
            return 60 if s.rsplit(unit, 1)[0][-1] in '13579' else 1
        elif unit == 'h':
            return 3600
        return 1

    total_seconds = 0

    # Find all number-unit pairs
    pairs = re.findall(r'(\d+)([smh])', s)

    for number, unit in pairs:
        multiplier = get_multiplier(unit)
        total_seconds += int(number) * multiplier

    # Handle bare numbers - extract all standalone numbers
    for match in re.finditer(r'\b(\d+)\b', s):
        num_str = match.group(1)
        num = int(num_str)
        # Check if this number is already part of a pair
        if num not in [int(n) for n, u in pairs]:
            total_seconds += num

    return total_seconds

